let paperSyncBusy=false,paperSyncedSignature=null;
async function syncPaper(){
 if(paperSyncBusy)return;paperSyncBusy=true;
 try{
  const remote=await api('/api/paper'),merged=mergePaperRecords(paper.read(),remote.records);paper.write(merged);
  const signature=JSON.stringify(merged);
  if(signature!==JSON.stringify(remote.records)){
   const saved=await api('/api/paper',{method:'POST',headers:{'Content-Type':'application/json','X-Bot-Write':'1'},body:JSON.stringify({baseVersion:remote.version,records:merged})});
   paper.write(mergePaperRecords(paper.read(),saved.records));
  }
  paperSyncedSignature=JSON.stringify(paper.read());$('paperSyncState').textContent='Libro PAPER guardado en nube y dispositivo · seguimiento por ticks mientras el panel está abierto.';
 }catch(e){$('paperSyncState').textContent='Copia del dispositivo conservada · '+(e.status===409?'Otra sesión actualizó el libro; se reconciliará en el próximo intento.':e.message);}
 finally{paperSyncBusy=false;panels?.renderPaper();}
}
function captureLocal(s){try{if(!journal)return false;return journal.observe(s)===true;}catch(e){$('error').textContent='No se pudo guardar la copia del dispositivo: '+e.message;return false;}}
