function quoteReceived(q){const key=q.market+':'+q.symbol,old=quotes.get(key);if(old&&q.ts<old.ts)return;q.direction=old?Math.sign(q.price-old.price):0;quotes.set(key,q);quoteRevision++;try{paper.quote(q);}catch(e){$('sizingStatus').textContent='No se pudo actualizar el seguimiento local: '+e.message;}if(q.source==='WS')wsMessages++;if(old&&old.price!==q.price)priceChanges++;}
async function startFeed(mySequence){const market=$('market').value,other=market==='PERP'?'SPOT':'PERP';try{const [c,alt]=await Promise.all([catalog(market),catalog(other)]);if(mySequence!==sequence)return;const symbols=c.data.filter(x=>supported(x,market)).map(x=>x.symbol),missing=alt.data.filter(x=>supported(x,other)&&!symbols.includes(x.symbol)).map(x=>x.symbol);feed?.stop();alternateFeed?.stop();feed=new LiveFeed({symbols,market,onQuote:quoteReceived,onState:s=>{$('connection').textContent=s.state==='RECIBIENDO'?'● Precios en vivo':s.state.replaceAll('_',' ');$('connection').className='badge '+(s.state==='RECIBIENDO'?'good':'warn');}});feed.start();if(missing.length){alternateFeed=new LiveFeed({symbols:missing,market:other,onQuote:quoteReceived});alternateFeed.start();}else alternateFeed=null;}catch(e){$('connection').textContent='WS pendiente · REST disponible';}}
