 for(const el of document.querySelectorAll('[data-quote]')){const market=el.dataset.quoteMarket||$('market').value,x=getDashboard().rows.find(r=>r.symbol===el.dataset.quote&&r.market===market);if(!x)continue;el.textContent=fmt(x.price);el.className=returnTone(x.displayChange);}for(const x of snapshot?.opportunities||[]){const q=qFor(x.symbol,x.market);if(freshQ(q)&&(x.side==='LONG'?q.price<=x.stop:q.price>=x.stop))invalidated.add(x.lifecycleId||x.id);}if(invalidated.size>2000)invalidated.delete(invalidated.values().next().value);
