let scanRun=null;
function load(){if(loading)return scanRun||Promise.resolve();loading=true;scanRun=collectCurrent();return scanRun;}
async function collectCurrent(){const taskRun=tasks.begin('price','Scanner Bitget · 54 activos','REGLAS_Y_OHLCV'),seq=sequence,symbol=$('symbol').value,market=$('market').value;$('error').textContent='';$('scanProgress').textContent='Leyendo activo y universo';try{const result=await acquire(symbol,fetch,{market,cancelled:()=>seq!==sequence,onProgress:p=>{if(seq===sequence)$('scanProgress').textContent='Radar '+p.done+' / '+p.total+' · '+market;},onPartial:async r=>{if(seq!==sequence)return;const partial=await analyzer.run(r);if(seq!==sequence)return;raw=r;snapshot=partial;renderAll();$('notice').textContent='Activo cargado. Completando el radar de las 54 en segundo plano…';}});if(seq!==sequence)return;const computed=await analyzer.run(result,snapshot);if(seq!==sequence)return;raw=result;snapshot=computed;const localSaved=captureLocal(snapshot);renderAll();$('notice').textContent='Análisis '+time(snapshot.received)+' · velas cerradas por temporalidad · actualización automática';lastLoad=Date.now();try{const j=await api('/api/ingest',{method:'POST',headers:{'Content-Type':'application/json','X-Bot-Write':'1'},body:JSON.stringify(raw)});if(seq===sequence&&j.version===VERSION){snapshot=j;renderAll();$('notice').textContent='Análisis '+time(snapshot.received)+' · guardado en nube';}}catch(e){if(seq===sequence)$('notice').textContent='Análisis en pantalla · '+(localSaved?'copia guardada en este dispositivo':'sin copia local')+' · '+(e.status===401?'restablecé la sesión para sincronizar':e.message);}}catch(e){if(seq===sequence){$('error').textContent='Lectura incompleta: '+e.message+'. El último dato conserva su fecha.';lastLoad=Date.now();}}finally{tasks.finish(taskRun,snapshot?'Cotizaciones y velas propias adquiridas':'Sin nueva captura',snapshot?'OK':'ERROR');if(seq===sequence)loading=false;}}
